const MD_range=(a,b,n)=>Array.from({length:n+1},(_,i)=>a+(b-a)*i/n);
const MD_GREY='#5C6577', MD_STEEL='#495057', MD_DARK='#343A40', MD_LIGHT='#DEE2E6', MD_RAD=Math.PI/180;
