  MD_T(334,y[0]+40,'trapezoidal, 30°',{fs:24,fw:800,fill:ORG})+MD_T(334,y[0]+68,'easier to cut',{fs:22,fill:MD_GREY})+
  `<polygon points="${sq.map(p=>p.join(',')).join(' ')}" fill="${BLU}" fill-opacity=".25" stroke="${BLU}" stroke-width="3"/>`+
  `<polygon points="${tr.map(p=>p.map(v=>v.toFixed(1)).join(',')).join(' ')}" fill="${ORG}" fill-opacity=".25" stroke="${ORG}" stroke-width="3"/>`;
